#!/usr/bin/env node
// Writes lib/skill-check.gen.js: the published half of Spacesheep's skill checker
// (shared/skill-format.ts's checkSkillFormat: SKILL.md as the Agent Skills spec reads it,
// spacesheep.yaml's shape, the folder's bytes and the version hash), built from a commit of
// the app's repo into one CommonJS file with the yaml parser it uses inside it. The CLI
// keeps no copy of its own: `spacesheep skills check` runs the code the server runs for
// the format, at the commit named in the file's header.
//
// Only skill-format.ts and skill-files.ts are taken out of the app's repo, so nothing else
// of it can reach the file: what a skill may declare it asks for or does is checked by the
// server's own rules (shared/skill-package.ts), which are never published. The build fails
// if the bundle would hold any other file of the app's.
//
//   node scripts/skill-check-bundle.mjs [--core <app repo>] [--rev <commit>]          write it
//   node scripts/skill-check-bundle.mjs [--core <app repo>] [--rev <commit>] --check  exit 1 if it is stale
//
// The app's repo is --core, else $SPACESHEEP_CORE, else ../spacesheep beside this repo. Its
// files are read at --rev (default origin/main), never from its working tree, and built
// with its own esbuild and yaml (node_modules), so this repo needs neither. Run it again
// after skill-format.ts changes; test/skill-check.test.js fails when the file is stale.
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const OUT = join(here, "..", "lib", "skill-check.gen.js");
/** The only files of the app's repo the bundle may hold. */
export const SOURCES = ["shared/skill-format.ts", "shared/skill-files.ts"];
const ENTRY = `export { checkSkillFormat, DECLARED_KEYS, SKILL_FILE_NAMES, SKILL_FORMAT_LIMITS } from "./shared/skill-format";
`;

/** Where the app's repo is: --core, $SPACESHEEP_CORE, or ../spacesheep beside this repo. */
export function corePath(argv = process.argv, env = process.env) {
  const i = argv.indexOf("--core");
  return resolve(i >= 0 ? argv[i + 1] : env.SPACESHEEP_CORE || join(here, "..", "..", "spacesheep"));
}

/** The file's text as it would be written from that repo at that commit. */
export async function build(core, rev = "origin/main") {
  const git = (...a) => execFileSync("git", ["-C", core, ...a], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
  const commit = git("rev-parse", "--verify", `${rev}^{commit}`);
  for (const f of SOURCES) git("cat-file", "-e", `${commit}:${f}`);
  const req = createRequire(join(core, "package.json"));
  const esbuild = req("esbuild");
  const yamlPkg = req.resolve("yaml/package.json");
  const yamlVersion = JSON.parse(readFileSync(yamlPkg, "utf8")).version;
  const yamlLicense = readFileSync(join(dirname(yamlPkg), "LICENSE"), "utf8").trim();

  // Built in a folder that holds only the two files and yaml (a link to the app's copy), so
  // nothing else can be resolved, and every path esbuild writes into the file is relative to
  // it: no folder of the machine that built it.
  const tmp = realpathSync(mkdtempSync(join(tmpdir(), "skill-check-")));
  try {
    execFileSync("sh", ["-c", `git -C "$1" archive "$2" -- ${SOURCES.join(" ")} | tar -x -C "$3"`, "sh", core, commit, tmp]);
    mkdirSync(join(tmp, "node_modules"));
    symlinkSync(dirname(yamlPkg), join(tmp, "node_modules", "yaml"));
    // yaml's ESM build (the "default" condition under platform neutral), so what the
    // checker doesn't use of it is left out.
    const r = await esbuild.build({
      stdin: { contents: ENTRY, resolveDir: tmp, sourcefile: "skill-check-entry.ts", loader: "ts" },
      absWorkingDir: tmp, bundle: true, platform: "neutral", format: "cjs", target: "node20",
      mainFields: ["module", "main"], preserveSymlinks: true,
      write: false, metafile: true, legalComments: "none", charset: "utf8", logLevel: "silent",
    });
    const ours = Object.keys(r.metafile.inputs).filter((p) => !p.startsWith("node_modules/yaml/") && p !== "skill-check-entry.ts").sort();
    const extra = ours.filter((p) => !SOURCES.includes(p));
    if (extra.length) throw new Error(`the bundle would hold ${extra.join(", ")}: only ${SOURCES.join(" and ")} may be published`);
    // The commit that last changed these files, so the header moves only when they do.
    const [changed, date] = git("log", "-1", "--format=%H %cs", commit, "--", ...SOURCES).split(" ");
    const built = { repo: "spacesheep-dev/spacesheep", commit: changed, date, files: ours, yaml: yamlVersion };
    return `// Generated by scripts/skill-check-bundle.mjs: don't edit, run it again.
// The published half of Spacesheep's skill checker (the format: SKILL.md, spacesheep.yaml's
// shape, the folder's bytes and the hash), built from spacesheep-dev/spacesheep at
// ${changed} (${date}, the last commit to change these files):
${ours.map((p) => `//   ${p}`).join("\n")}
// with yaml ${yamlVersion}, whose licence follows:
${yamlLicense.split("\n").map((l) => `//   ${l}`.trimEnd()).join("\n")}
/* eslint-disable */
${r.outputFiles[0].text}module.exports.BUILT_FROM = ${JSON.stringify(built)};
`;
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const argv = process.argv;
  const at = argv.indexOf("--rev");
  const text = await build(corePath(argv), at >= 0 ? argv[at + 1] : "origin/main");
  const said = `${Buffer.byteLength(text)} bytes`;
  if (argv.includes("--check")) {
    let now = "";
    try { now = readFileSync(OUT, "utf8"); } catch { /* missing reads as stale */ }
    if (now !== text) {
      console.error("lib/skill-check.gen.js is stale: run node scripts/skill-check-bundle.mjs");
      process.exit(1);
    }
    console.log(`skill-check.gen.js is current (${said})`);
  } else {
    writeFileSync(OUT, text);
    console.log(`wrote lib/skill-check.gen.js (${said})`);
  }
}
